[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$Destination)
$ErrorActionPreference='Stop';$d=[IO.Path]::GetFullPath($Destination);if(Test-Path $d){throw 'PORTABLE_TARGET_EXISTS'};New-Item -ItemType Directory -Force (Join-Path $d 'pages')|Out-Null
$pages=@();1..19|%{$id="PAGE-PORT-$('{0:D2}' -f $_)";$parent=if($_ -eq 1){$null}else{'PAGE-PORT-01'};Set-Content (Join-Path $d "pages/$id.md") "---`nid: $id`nparent: $parent`nversion: 1`nstatus: published`n---`n# Synthetic page $id" -Encoding utf8;$pages+=[ordered]@{id=$id;parent=$parent;version=1;status='published';sourcePath="pages/$id.md"}}
$e=[ordered]@{id='EVID-PORT-01';hash=('a'*64);type='synthetic'};$tickets=@();1..17|%{$id="TKT-PORT-$('{0:D2}' -f $_)";$h=if($_ -le 16){5}else{0};$tickets+=[ordered]@{id=$id;status='closed';priority='P3';created='2026-02-01T09:00:00Z';status_history=@([ordered]@{status='open';time='2026-02-01T09:00:00Z'},[ordered]@{status='closed';time='2026-02-03T09:00:00Z'});acceptance=@('pass');evidence=@('EVID-PORT-01');comments=@([ordered]@{id="COM-$id-1";type='working';time='2026-02-02T09:00:00Z'},[ordered]@{id="COM-$id-2";type='closing';time='2026-02-03T09:00:00Z'});worklogs=@([ordered]@{id="WL-$id";hours=$h;cost=($h*120);date='2026-02-02'})}}
$events=@();1..15|%{$events+=[ordered]@{id="EV-PORT-$('{0:D2}' -f $_)";time="2026-02-$('{0:D2}' -f (($_%20)+1))T10:00:00Z";phase='implementation';references=@('PAGE-PORT-01','TKT-PORT-01','EVID-PORT-01','SESSION-PORT-01','DECISION-PORT-01','DELIVERABLE-PORT-01');nextStep='continue'}}
$story=[ordered]@{project_id='PROJECT-PORTABLE';story_id='STORY-PORTABLE';classification='synthetic';status='hypercare';offer=[ordered]@{versions=@(1,2,3);start_time='2026-02-01T00:00:00Z';end_time='2026-02-20T23:59:59Z';planned_hours=100;actual_hours=80;planned_cost=12000;actual_cost=9600};pages=$pages;tickets=$tickets;timeline=$events;hypercare=@(1,2,3|%{[ordered]@{day=$_;status='closed';daily_page='PAGE-PORT-01';go_no_go='GO'}});evidence=@($e);sessions=@([ordered]@{id='SESSION-PORT-01'});decisions=@([ordered]@{id='DECISION-PORT-01'});deliverables=@([ordered]@{id='DELIVERABLE-PORT-01'});graph=@()};$story|ConvertTo-Json -Depth 30|Set-Content (Join-Path $d 'project-story.json') -Encoding utf8;Write-Host 'PASS: Portable conformance fixture generated.'
